	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "todo_owner_check" CHECK ("todo"."owner" in ('operator', 'reggie', 'client')),
	CONSTRAINT "todo_title_check" CHECK (char_length("todo"."title") between 1 and 300),
	CONSTRAINT "todo_detail_check" CHECK (char_length("todo"."detail") <= 4000),
	CONSTRAINT "todo_why_check" CHECK ("todo"."why" is null or char_length("todo"."why") <= 300),
	CONSTRAINT "todo_about_kind_check" CHECK ("todo"."about_kind" is null or "todo"."about_kind" in ('issue', 'client_ask', 'enhancement', 'build', 'deal', 'question', 'run', 'client')),
	CONSTRAINT "todo_about_check" CHECK (("todo"."about_kind" is null) = ("todo"."about_id" is null)),
	CONSTRAINT "todo_state_check" CHECK ("todo"."state" in ('open', 'done', 'snoozed', 'dropped')),
